86	using Items = std::unordered_multimap<const IKey *, std::shared_ptr<CacheItem>, HashKey, KeyEqual>;
87	
88	struct Cache::Impl
89	{
90	    Items                                          items;
91	    inline static std::mutex                       mtx;
92	    inline static std::unordered_map<int, int64_t> cache_limit_inbytes;
93	    inline static std::unordered_map<int, int64_t> current_size_inbytes;
94	};
95	
96	Cache::Cache()
97	{
98	    pimpl = std::make_unique<Impl>();
99	    std::lock_guard lk(Impl::mtx);
100	    instances.insert(this);
101	}
102	
103	Cache::~Cache() noexcept
104	{
105	    std::unique_ptr<Impl> localPimpl;
106	
107	    try
108	    {
109	        {
110	            std::lock_guard lk(Impl::mtx);
111	            instances.erase(this);
112	            // It might not be safe to call destructors here, decrease the size manually
113	            for (const auto &[nodeKey, node] : pimpl->items)
114	            {
115	                int dev = nodeKey->deviceId();
116	                Impl::current_size_inbytes[dev] -= node->GetSizeInBytes();
117	            }
118	        }
119	
120	        localPimpl = std::move(this->pimpl);
121	#if PY_MAJOR_VERSION >= 3 && PY_MINOR_VERSION >= 13
122	        if (Py_IsInitialized() && !Py_IsFinalizing())
123	#else
124	        if (Py_IsInitialized())
125	#endif
126	        {
127	            // Make sure that the main thread doesn't finalize the interpreter until all objects have been destroyed
128	            py::gil_scoped_acquire acq;
129	            localPimpl.reset();
130	        }
131	        else
132	        {
133	            localPimpl.release();
134	        }
135	    }
136	    catch (...)
137	    {
138	        // Leak intentionally if the Python runtime is not available anymore.
139	        // See https://pybind11.readthedocs.io/en/stable/advanced/misc.html#common-sources-of-global-interpreter-lock-errors
140	        if (localPimpl)
141	        {
142	            localPimpl.release();
143	        }
144	        if (pimpl)
145	        {
146	            pimpl.release();
147	        }
148	    }
149	}
