224	std::vector<std::shared_ptr<CacheItem>> Cache::fetch(const IKey &key) const
225	{
226	    std::vector<std::shared_ptr<CacheItem>> v;
227	
228	    std::unique_lock lk(Impl::mtx);
229	
230	    auto [firstItem, lastItem] = pimpl->items.equal_range(&key);
231	
232	    v.reserve(distance(firstItem, lastItem));
233	
234	    for (auto it = firstItem; it != lastItem; ++it)
235	    {
236	        if (!it->second->isInUse())
237	        {
238	            v.emplace_back(it->second);
239	        }
240	    }
241	
242	    return v;
243	}
