286	void Cache::setCacheLimit(int64_t new_cache_limit_inbytes)
287	{
288	    if (new_cache_limit_inbytes < 0)
289	    {
290	        throw std::invalid_argument("Cache limit must be non-negative.");
291	    }
292	
293	    int dev = 0;
294	    util::CheckThrow(cudaGetDevice(&dev));
295	
296	    size_t free_mem;
297	    size_t total_mem;
298	    util::CheckThrow(cudaMemGetInfo(&free_mem, &total_mem));
299	
300	    if (static_cast<int64_t>(total_mem) < new_cache_limit_inbytes)
301	    {
302	        std::cerr << "WARNING: new_cache_limit=" << new_cache_limit_inbytes
303	                  << " is more than total available memory on device " << dev << ": " << total_mem << std::endl;
304	    }
305	
306	    Items savedItems;
307	    {
308	        std::unique_lock lk(Impl::mtx);
309	        if (doGetDeviceSize(dev) > new_cache_limit_inbytes)
310	        {
311	            // Evict only items belonging to this device.
312	            for (auto it = pimpl->items.begin(); it != pimpl->items.end();)
313	            {
314	                if (it->first->deviceId() == dev)
315	                {
316	                    savedItems.insert(pimpl->items.extract(it++));
317	                }
318	                else
319	                {
320	                    ++it;
321	                }
322	            }
323	            Impl::current_size_inbytes[dev] = 0;
324	        }
325	        Impl::cache_limit_inbytes[dev] = new_cache_limit_inbytes;
326	    }
327	}
