382	void Cache::ClearAll()
383	{
384	    Items savedItems;
385	    {
386	        std::lock_guard lk(Cache::Impl::mtx);
387	        std::for_each(instances.begin(), instances.end(),
388	                      [&savedItems](Cache *instance) { savedItems.merge(instance->pimpl->items); });
389	        Cache::Impl::current_size_inbytes.clear();
390	    }
391	}
392	
393	size_t Cache::TotalSize()
394	{
395	    std::lock_guard lk(Cache::Impl::mtx);
396	    return std::accumulate(instances.cbegin(), instances.cend(), static_cast<size_t>(0),
397	                           [](size_t sum, const Cache *instance) { return sum + instance->size(); });
398	}
